package com.eap.platform.ax;

import com.eap.platform.ax.proto.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class AxActorIdentityTests {
 private static final String UID="56592f45-ed6b-4d34-8d20-909957c16946";
 private static final String IMAGE="registry/eap-task@sha256:"+"a".repeat(64);
 private Task.Builder task(){return Task.newBuilder().setMetadata(ObjectMeta.newBuilder().setAtespace("eap-ax").setName("task"))
  .setSpec(TaskSpec.newBuilder().setImage(IMAGE).addEnv(EnvVar.newBuilder().setName("EAP_IDENTITY_MODE").setValue(AxActorIdentity.MODE)))
  .setStatus(TaskStatus.newBuilder().setActor("task").setId("task-task-123456789").setPhase("Running").addConditions(Condition.newBuilder().setType("Ready").setStatus("True")));}
 private Condition receipt(String uid,String template){return Condition.newBuilder().setType(AxActorIdentity.CONDITION).setStatus("True").setReason("CreateReceiptBound").setMessage("{\"actorUid\":\""+uid+"\",\"actorTemplate\":\""+template+"\"}").build();}
 @Test void onlyNativeCreateReceiptProvidesUid(){var t=task();t.getStatusBuilder().addConditions(receipt(UID,"eap-ax/template"));var state=AxActorIdentity.state(t.build());assertTrue(state.ready());assertTrue(state.instanceIdentity());assertEquals(UID,state.actorUid());assertEquals("eap-ax/template",state.actorTemplate());assertNotEquals(t.getStatus().getId(),state.actorUid());}
 @Test void readyWithoutCreateReceiptIsNotIdentityReady(){var state=AxActorIdentity.state(task().build());assertFalse(state.ready());assertTrue(state.instanceIdentity());assertNull(state.actorUid());}
 @Test void legacyTaskKeepsLegacyStateAndDoesNotAdoptUid(){var t=task();t.getSpecBuilder().clearEnv();t.getStatusBuilder().addConditions(receipt(UID,"eap-ax/template"));var state=AxActorIdentity.state(t.build());assertTrue(state.ready());assertFalse(state.instanceIdentity());assertNull(state.actorUid());}
 @Test void changedOrUnconfirmedIdentityIsNotReady(){var t=task();t.getStatusBuilder().addConditions(receipt(UID,"eap-ax/template").toBuilder().setStatus("False").setReason("IdentityUnconfirmed"));assertFalse(AxActorIdentity.state(t.build()).ready());}
 @Test void malformedForeignAndDuplicateReceiptsAreRejected(){
  for(var c:List.of(receipt("not-a-uid","eap-ax/template"),receipt(UID,"foreign/template"),receipt(UID,"eap-ax/../foreign"),receipt(UID,"eap-ax/template").toBuilder().setMessage("{\"actorUid\":\""+UID+"\",\"actorTemplate\":\"eap-ax/template\",\"extra\":true}").build())){var t=task();t.getStatusBuilder().addConditions(c);assertThrows(IllegalStateException.class,()->AxActorIdentity.state(t.build()));}
  var duplicate=task();duplicate.getStatusBuilder().addConditions(receipt(UID,"eap-ax/template")).addConditions(receipt(UID,"eap-ax/template"));assertThrows(IllegalStateException.class,()->AxActorIdentity.state(duplicate.build()));
 }
 @Test void statusCannotBindAnotherActorName(){var t=task();t.getStatusBuilder().setActor("foreign").addConditions(receipt(UID,"eap-ax/template"));assertThrows(IllegalStateException.class,()->AxActorIdentity.state(t.build()));}
 @Test void existingTaskMustMatchFrozenImageAndPublicConfiguration(){var t=task().build();var env=Map.of("EAP_IDENTITY_MODE",AxActorIdentity.MODE);assertDoesNotThrow(()->AxActorIdentity.verifyFrozen(t,"eap-ax","task",IMAGE,env));assertThrows(IllegalStateException.class,()->AxActorIdentity.verifyFrozen(t,"eap-ax","task",IMAGE.replace("a","b"),env));assertThrows(IllegalStateException.class,()->AxActorIdentity.verifyFrozen(t,"eap-ax","task",IMAGE,Map.of("EAP_IDENTITY_MODE",AxActorIdentity.MODE,"EAP_IDENTITY_PUBLIC_KEY","changed")));}
 @Test void duplicateIdentityModeCannotFallBackToLegacy(){var t=task();t.getSpecBuilder().addEnv(EnvVar.newBuilder().setName("EAP_IDENTITY_MODE").setValue(""));assertThrows(IllegalStateException.class,()->AxActorIdentity.state(t.build()));}
 @Test void nativeGoControllerReceiptSurvivesJavaProtobufWire()throws Exception{
  try(var input=getClass().getResourceAsStream("/ax-instance-identity.pb")){
   assertNotNull(input,"fixture must be generated by the tested Go controller");
   var task=Task.parseFrom(input);var state=AxActorIdentity.state(task);
   assertEquals(UID,state.actorUid());assertTrue(state.instanceIdentity());assertTrue(state.actorTemplate().startsWith("eap-ax/"));assertFalse(state.ready());
   assertEquals("Suspended",state.phase());assertNotEquals(task.getStatus().getId(),state.actorUid());
  }
 }
 @Test void duplicateJsonFieldsCannotChangeNativeReceipt(){var t=task();t.getStatusBuilder().addConditions(receipt(UID,"eap-ax/template").toBuilder().setMessage("{\"actorUid\":\"foreign\",\"actorUid\":\""+UID+"\",\"actorTemplate\":\"eap-ax/template\"}"));assertThrows(IllegalStateException.class,()->AxActorIdentity.state(t.build()));}
}
